Source: `client/src/lib/vestibularSchwaноmaLogic.ts`

```typescript
/**
 * Vestibular Schwannoma Clinical Logic Engine
 *
 * Based on:
 * - CNS 2025 Evidence-Based Clinical Practice Guidelines for Vestibular Schwannoma
 *   (Neurosurgery, 2025 — Multiple domains: Surgery, SRS, Hearing Preservation, Imaging, CN Monitoring)
 * - AAO-HNS Acoustic Neuroma Guidelines
 * - NOMS Framework for decision-making
 *
 * Key guideline authors: Olson JJ, Carlson ML, Van Gompel JJ, Germano IM, Graffeo CS (CNS 2025)
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type TumorSizeClass =
  | "intracanalicular" // confined to IAC
  | "small" // <1.5 cm CPA
  | "medium" // 1.5–3 cm CPA
  | "large"; // >3 cm CPA

export type HearingClass =
  | "class_a" // AAO-HNS Class A: PTA ≤30 dB, WRS ≥70%
  | "class_b" // AAO-HNS Class B: PTA ≤50 dB, WRS ≥50%
  | "class_c" // AAO-HNS Class C: any PTA, WRS ≥50%
  | "class_d" // AAO-HNS Class D: non-serviceable
  | "non_serviceable"; // SDS <50% or PTA >50 dB

export type GardnerRobertsonGrade =
  | "gr1" // Excellent: PTA ≤30, WRS 70–100%
  | "gr2" // Good: PTA 31–50, WRS 50–69%
  | "gr3" // Serviceable: PTA 51–90, WRS 5–49%
  | "gr4" // Poor: PTA 91+, WRS 1–4%
  | "gr5"; // None: WRS 0%

export type PrimaryRecommendation =
  | "observation_active_surveillance"
  | "srs_gamma_knife"
  | "microsurgery_resection"
  | "fractionated_srt"
  | "subtotal_resection_plus_srs"
  | "multidisciplinary_nf2"
  | "urgent_decompression";

export interface VestibularSchwaноmaInput {
  // Tumor characteristics
  tumorSizeClass: TumorSizeClass;
  tumorSizeCm: number;
  cysticComponent: boolean;
  lateralIACInvolvement: boolean; // fundal cap absent
  fundalCSFCap: boolean; // protective for hearing preservation

  // Hearing status
  hearingClass: HearingClass;
  gardnerRobertsonGrade: GardnerRobertsonGrade;
  serviceableHearing: boolean; // Class A or B / GR 1 or 2
  suddenSNHL: boolean;
  asymmetricTinnitus: boolean;
  asymmetricSNHL: boolean;

  // Tumor behavior
  priorObservation: boolean;
  tumorGrowthOnObservation: boolean; // growth ≥2mm in any dimension
  observationDurationMonths?: number;

  // Patient factors
  ageYears: number;
  nf2Status: boolean;
  contralateralHearingLoss: boolean;
  trigeminalNeuralgiaSymptoms: boolean;
  balanceProblems: boolean;
  facialNerveFunctionHB: 1 | 2 | 3 | 4 | 5 | 6; // House-Brackmann grade

  // Treatment history
  priorSRS: boolean;
  priorSurgery: boolean;

  // Patient preferences
  hearingPreservationPriority: boolean;
  preferMinimallyInvasive: boolean;

  // SRS parameters (if applicable)
  cochlearDoseGy?: number;
  marginalDoseGy?: number;
}

export interface VestibularSchwaноmaRecommendation {
  primaryRecommendation: PrimaryRecommendation;
  recommendationTitle: string;
  rationale: string;
  evidenceLevel: "I" | "II" | "III";
  guidelineSource: string;

  // Hearing preservation counseling
  hearingPreservationCounseling: string[];

  // Treatment-specific notes
  surgicalNotes: string[];
  srsNotes: string[];
  observationNotes: string[];

  // Monitoring
  monitoringPlan: string[];

  // Warnings and flags
  urgentFlags: string[];
  warnings: string[];

  // Next steps
  nextSteps: string[];

  // References
  references: Array<{ citation: string; pmid?: string }>;
}

// ─── Core Logic ──────────────────────────────────────────────────────────────

export function assessVestibularSchwanoma(
  input: VestibularSchwaноmaInput
): VestibularSchwaноmaRecommendation {
  const urgentFlags: string[] = [];
  const warnings: string[] = [];
  const hearingPreservationCounseling: string[] = [];
  const surgicalNotes: string[] = [];
  const srsNotes: string[] = [];
  const observationNotes: string[] = [];
  const monitoringPlan: string[] = [];

  // ── Diagnostic flags ──────────────────────────────────────────────────────
  if (input.suddenSNHL) {
    urgentFlags.push(
      "Sudden SNHL: MRI with gadolinium is suggested to evaluate for vestibular schwannoma (CNS 2025, Level III)."
    );
  }
  if (input.asymmetricSNHL || input.asymmetricTinnitus) {
    urgentFlags.push(
      "Asymmetric SNHL or tinnitus: MRI screening is suggested (CNS 2025, Level III)."
    );
  }

  // ── NF2 pathway ───────────────────────────────────────────────────────────
  if (input.nf2Status) {
    warnings.push(
      "NF2 (Neurofibromatosis Type 2): Bilateral vestibular schwannomas. Bevacizumab may be considered for hearing preservation. SRS is an option for enlarging or hearing-loss-causing tumors. Surgical planning must consider contralateral hearing."
    );
    if (input.contralateralHearingLoss) {
      urgentFlags.push(
        "NF2 with contralateral hearing loss: Only-hearing ear situation. Hearing preservation is paramount — auditory brainstem implant (ABI) planning may be required."
      );
    }
    return {
      primaryRecommendation: "multidisciplinary_nf2",
      recommendationTitle: "Multidisciplinary NF2 Management",
      rationale:
        "NF2-associated vestibular schwannomas require specialized multidisciplinary management. Bevacizumab may improve hearing and reduce tumor growth. SRS is a treatment option for enlarging tumors or those causing hearing loss (CNS 2025, Level III).",
      evidenceLevel: "III",
      guidelineSource:
        "CNS 2025 Vestibular Schwannoma Guidelines (Olson JJ et al., Neurosurgery 2025)",
      hearingPreservationCounseling: [
        "NF2: Hearing preservation is the primary goal of management.",
        "Bevacizumab (anti-VEGF): Evidence for hearing improvement and tumor stabilization in NF2.",
        "SRS: Option for enlarging tumors — counsel on hearing preservation rates (moderately high at 2–5 years).",
        "Auditory brainstem implant (ABI) planning if hearing loss is anticipated.",
      ],
      surgicalNotes: [
        "Surgery in NF2: Subtotal resection (STR) followed by SRS may preserve facial nerve function.",
        "Microsurgical resection after prior SRS: Increased likelihood of STR and decreased facial nerve function.",
      ],
      srsNotes: [
        "SRS cochlear dose constraint: <4 Gy single fraction, <35 Gy fractionated.",
        "Single fraction SRS preferred over hypofractionated SRS for decreased cranial nerve dysfunction (CNS 2025).",
      ],
      observationNotes: [
        "Annual MRI surveillance for NF2 tumors not requiring immediate intervention.",
      ],
      monitoringPlan: [
        "Annual MRI with gadolinium",
        "Annual audiogram",
        "Multidisciplinary NF2 clinic follow-up",
        "Genetic counseling for family members",
      ],
      urgentFlags,
      warnings,
      nextSteps: [
        "Refer to NF2 multidisciplinary center",
        "Neurology, neurosurgery, otolaryngology, and audiology co-management",
        "Genetic counseling",
        "Consider bevacizumab trial if hearing deterioration",
        "ABI planning consultation if bilateral hearing loss anticipated",
      ],
      references: getVSReferences(),
    };
  }

  // ── Large tumor (>3 cm) — surgery preferred ───────────────────────────────
  if (input.tumorSizeClass === "large" || input.tumorSizeCm > 3) {
    urgentFlags.push(
      "Large tumor (>3 cm): Brainstem compression risk. Surgical resection is typically indicated."
    );
    if (input.facialNerveFunctionHB > 2) {
      warnings.push(
        "Facial nerve function already compromised (HB >2): Intraoperative cranial nerve monitoring essential."
      );
    }
    surgicalNotes.push(
      "Large VS: Subtotal resection (STR) + adjuvant SRS may be considered to preserve facial nerve function."
    );
    surgicalNotes.push(
      "Intraoperative facial nerve monitoring is standard of care."
    );
    surgicalNotes.push(
      "Cystic VS: Lower complete resection rates and inferior immediate postoperative facial nerve outcomes (CNS 2025)."
    );
    if (input.cysticComponent) {
      warnings.push(
        "Cystic VS: Associated with rapid growth, lower complete resection rates, and inferior immediate postoperative facial nerve outcomes."
      );
    }

    return buildSurgeryRecommendation(
      input,
      urgentFlags,
      warnings,
      surgicalNotes,
      srsNotes,
      observationNotes,
      monitoringPlan,
      hearingPreservationCounseling
    );
  }

  // ── Intracanalicular or small (<1.5 cm) — observation vs SRS ─────────────
  if (
    input.tumorSizeClass === "intracanalicular" ||
    input.tumorSizeClass === "small"
  ) {
    // Hearing preservation counseling for serviceable hearing
    if (input.serviceableHearing) {
      hearingPreservationCounseling.push(
        "Serviceable hearing + observation: HP rate >75% at 2 years, >50% at 5 years, >25% at 10 years (CNS 2025, Level III)."
      );
      hearingPreservationCounseling.push(
        "Serviceable hearing + SRS (single fraction): HP rate >50% at 2 and 5 years, >25% at 10 years. Better outcomes with cochlear dose ≤4 Gy, marginal dose ≤13 Gy, and Class A/GR I status (CNS 2025, Level III)."
      );
      hearingPreservationCounseling.push(
        "Serviceable hearing + microsurgery: HP rate >25% immediately and at 2, 5, 10 years. Better outcomes with Class A/GR I status, smaller tumor, and fundal CSF cap present (CNS 2025, Level III)."
      );
      hearingPreservationCounseling.push(
        "IMPORTANT: For sporadic intracanalicular or <2 cm VS with hearing preservation goal — SRS is NOT superior to observation for hearing preservation (CNS 2025, Level III)."
      );
    }

    // No growth on observation — continue observation
    if (input.priorObservation && !input.tumorGrowthOnObservation) {
      observationNotes.push(
        "No tumor growth on observation: Continue active surveillance."
      );
      observationNotes.push(
        "MRI every 12 months × 3 years, then every 2 years if stable."
      );
      return buildObservationRecommendation(
        input,
        urgentFlags,
        warnings,
        surgicalNotes,
        srsNotes,
        observationNotes,
        monitoringPlan,
        hearingPreservationCounseling
      );
    }

    // Growth documented — offer treatment
    if (input.tumorGrowthOnObservation) {
      warnings.push(
        "Tumor growth documented on observation: Treatment should be discussed. SRS or microsurgery depending on patient factors."
      );
    }

    // Default for small/intracanalicular: observation or SRS
    if (!input.tumorGrowthOnObservation && !input.priorObservation) {
      return buildObservationRecommendation(
        input,
        urgentFlags,
        warnings,
        surgicalNotes,
        srsNotes,
        observationNotes,
        monitoringPlan,
        hearingPreservationCounseling
      );
    }
  }

  // ── Medium tumor (1.5–3 cm) — shared decision-making ─────────────────────
  if (input.tumorSizeClass === "medium") {
    if (input.serviceableHearing && input.hearingPreservationPriority) {
      srsNotes.push(
        "Medium VS with serviceable hearing: SRS may offer hearing preservation rates comparable to observation at 2–5 years."
      );
      srsNotes.push(
        "Cochlear dose constraint: Single fraction <4 Gy, fractionated <35 Gy (CNS 2025)."
      );
      srsNotes.push(
        "Single fraction SRS preferred over hypofractionated SRS for decreased cranial nerve dysfunction."
      );
      return buildSRSRecommendation(
        input,
        urgentFlags,
        warnings,
        surgicalNotes,
        srsNotes,
        observationNotes,
        monitoringPlan,
        hearingPreservationCounseling
      );
    }

    if (input.trigeminalNeuralgiaSymptoms) {
      surgicalNotes.push(
        "Trigeminal neuralgia symptoms: Surgical resection may better relieve symptoms compared to SRS (CNS 2025, Level III)."
      );
      return buildSurgeryRecommendation(
        input,
        urgentFlags,
        warnings,
        surgicalNotes,
        srsNotes,
        observationNotes,
        monitoringPlan,
        hearingPreservationCounseling
      );
    }
  }

  // ── Prior SRS — retreatment considerations ────────────────────────────────
  if (input.priorSRS) {
    warnings.push(
      "Prior SRS: Microsurgical resection after SRS carries increased likelihood of subtotal resection (STR) and decreased facial nerve function (CNS 2025, Level III)."
    );
    surgicalNotes.push(
      "Post-SRS surgery: STR + facial nerve preservation is the primary goal. Complete resection may not be achievable."
    );
  }

  // ── Default: SRS for medium tumors or growing small tumors ───────────────
  return buildSRSRecommendation(
    input,
    urgentFlags,
    warnings,
    surgicalNotes,
    srsNotes,
    observationNotes,
    monitoringPlan,
    hearingPreservationCounseling
  );
}

// ─── Recommendation Builders ──────────────────────────────────────────────────

function buildObservationRecommendation(
  input: VestibularSchwaноmaInput,
  urgentFlags: string[],
  warnings: string[],
  surgicalNotes: string[],
  srsNotes: string[],
  observationNotes: string[],
  monitoringPlan: string[],
  hearingPreservationCounseling: string[]
): VestibularSchwaноmaRecommendation {
  return {
    primaryRecommendation: "observation_active_surveillance",
    recommendationTitle: "Active Surveillance — Observation with Serial MRI",
    rationale:
      "Active surveillance is appropriate for small/intracanalicular vestibular schwannomas, especially in older patients or those with serviceable hearing where treatment risks may outweigh benefits. CNS 2025 notes that SRS is NOT superior to observation for hearing preservation in sporadic intracanalicular or <2 cm VS.",
    evidenceLevel: "III",
    guidelineSource:
      "CNS 2025 Vestibular Schwannoma Guidelines (Olson JJ et al., Neurosurgery 2025)",
    hearingPreservationCounseling,
    surgicalNotes,
    srsNotes,
    observationNotes: [
      ...observationNotes,
      "Serial MRI: Every 6 months × 2 years, then annually × 3 years, then every 2 years if stable.",
      "Annual audiogram to monitor hearing.",
      "Trigger for treatment: growth ≥2 mm in any dimension, hearing deterioration, new symptoms.",
    ],
    monitoringPlan: [
      "MRI with gadolinium at 6 months, 12 months, then annually",
      "Annual audiogram",
      "Vestibular function testing if balance issues develop",
    ],
    urgentFlags,
    warnings: [
      ...warnings,
      input.cysticComponent
        ? "Cystic VS: Associated with rapid growth — shorter observation intervals recommended."
        : "",
    ].filter(Boolean),
    nextSteps: [
      "MRI with gadolinium in 6 months",
      "Annual audiogram",
      "Counsel patient on observation vs treatment trade-offs",
      "Discuss triggers for treatment: growth, hearing loss, new symptoms",
      "Refer to skull base multidisciplinary team for shared decision-making",
    ],
    references: getVSReferences(),
  };
}

function buildSRSRecommendation(
  input: VestibularSchwaноmaInput,
  urgentFlags: string[],
  warnings: string[],
  surgicalNotes: string[],
  srsNotes: string[],
  observationNotes: string[],
  monitoringPlan: string[],
  hearingPreservationCounseling: string[]
): VestibularSchwaноmaRecommendation {
  return {
    primaryRecommendation: "srs_gamma_knife",
    recommendationTitle:
      "Stereotactic Radiosurgery (SRS / Gamma Knife) — Recommended",
    rationale:
      "SRS provides excellent local tumor control (>90% at 5 years) for small-to-medium vestibular schwannomas with lower procedural risk than microsurgery. CNS 2025 recommends single fraction SRS over hypofractionated SRS for decreased cranial nerve dysfunction.",
    evidenceLevel: "III",
    guidelineSource:
      "CNS 2025 Vestibular Schwannoma Guidelines — Radiosurgery (Germano IM et al., Neurosurgery 2025)",
    hearingPreservationCounseling: [
      ...hearingPreservationCounseling,
      "SRS hearing preservation: >50% at 2–5 years with cochlear dose ≤4 Gy and marginal dose ≤13 Gy.",
      "Cochlear dose >4.2 Gy in single fraction associated with higher hearing loss risk.",
    ],
    surgicalNotes,
    srsNotes: [
      ...srsNotes,
      "Marginal dose: 12–13 Gy (single fraction) recommended for tumor control.",
      "Cochlear dose constraint: <4 Gy single fraction, <35 Gy fractionated.",
      "Single fraction SRS preferred over hypofractionated SRS (CNS 2025, Level III).",
      "Tumor control rate: >90% at 5 years, >85% at 10 years.",
      "Facial nerve preservation: >95% at experienced centers.",
    ],
    observationNotes,
    monitoringPlan: [
      "MRI at 6 months post-SRS, then annually × 5 years",
      "Annual audiogram",
      "Facial nerve function assessment at each visit",
      "Trigeminal function assessment",
    ],
    urgentFlags,
    warnings: [
      ...warnings,
      "SRS does not remove the tumor — radiographic 'expansion' in first 6–12 months is common and does not indicate treatment failure.",
      input.tumorSizeCm > 2.5
        ? "Tumor >2.5 cm: SRS may have higher risk of brainstem edema. Consider fractionated SRT."
        : "",
    ].filter(Boolean),
    nextSteps: [
      "Radiation oncology consultation for SRS planning",
      "Skull base multidisciplinary team review",
      "Audiogram before treatment",
      "Ophthalmology evaluation if trigeminal symptoms",
      "Counsel on 6–12 month radiographic expansion (pseudoprogression)",
      "MRI at 6 months post-SRS",
    ],
    references: getVSReferences(),
  };
}

function buildSurgeryRecommendation(
  input: VestibularSchwaноmaInput,
  urgentFlags: string[],
  warnings: string[],
  surgicalNotes: string[],
  srsNotes: string[],
  observationNotes: string[],
  monitoringPlan: string[],
  hearingPreservationCounseling: string[]
): VestibularSchwaноmaRecommendation {
  const approach =
    input.serviceableHearing && input.hearingPreservationPriority
      ? "Middle fossa or retrosigmoid approach (hearing preservation intent)"
      : "Translabyrinthine approach (if hearing non-serviceable — best facial nerve exposure)";

  return {
    primaryRecommendation: "microsurgery_resection",
    recommendationTitle: "Microsurgical Resection — Recommended",
    rationale:
      "Microsurgical resection is indicated for large tumors (>3 cm), tumors causing brainstem compression, or when trigeminal neuralgia symptoms are present. Intraoperative cranial nerve monitoring is standard of care.",
    evidenceLevel: "III",
    guidelineSource:
      "CNS 2025 Vestibular Schwannoma Guidelines — Surgery (Van Gompel JJ et al., Neurosurgery 2025)",
    hearingPreservationCounseling: [
      ...hearingPreservationCounseling,
      input.serviceableHearing
        ? "Microsurgery hearing preservation: >25% at 2, 5, 10 years. Better with Class A/GR I, smaller tumor, fundal CSF cap present."
        : "Hearing non-serviceable: Translabyrinthine approach provides best facial nerve exposure.",
      input.fundalCSFCap
        ? "Fundal CSF cap present: Associated with better hearing preservation outcomes."
        : "Fundal CSF cap absent (lateral IAC involvement): Reduced hearing preservation likelihood.",
    ],
    surgicalNotes: [
      ...surgicalNotes,
      approach,
      "Intraoperative facial nerve monitoring: Standard of care (CNS 2025).",
      "Intraoperative auditory monitoring (ABR or CNAP) if hearing preservation intent.",
      input.cysticComponent
        ? "Cystic VS: Lower complete resection rates and inferior immediate postoperative facial nerve outcomes — counsel patient."
        : "",
      input.priorSRS
        ? "Prior SRS: Increased likelihood of STR and decreased facial nerve function (CNS 2025, Level III)."
        : "",
      "STR + adjuvant SRS: Acceptable alternative to GTR for large tumors to preserve facial nerve.",
    ].filter(Boolean),
    srsNotes,
    observationNotes,
    monitoringPlan: [
      "MRI at 3 months postoperatively",
      "Annual MRI × 5 years",
      "Audiogram at 3 months postoperatively",
      "Facial nerve function assessment (House-Brackmann) at each visit",
      "Vestibular rehabilitation if balance issues persist",
    ],
    urgentFlags,
    warnings: [
      ...warnings,
      "Facial nerve injury risk: Varies by tumor size and adherence. Experienced skull base surgeon essential.",
      input.tumorSizeCm > 3
        ? "Large tumor: Consider STR + SRS strategy to optimize facial nerve preservation."
        : "",
    ].filter(Boolean),
    nextSteps: [
      "Refer to high-volume skull base neurosurgery center",
      "Multidisciplinary skull base team review (neurosurgery + otolaryngology)",
      "Preoperative audiogram",
      "Preoperative MRI with thin-cut IAC protocol",
      "Discuss STR vs GTR trade-offs (facial nerve preservation vs recurrence risk)",
      "Vestibular rehabilitation referral postoperatively",
    ],
    references: getVSReferences(),
  };
}

// ─── Helper Functions ─────────────────────────────────────────────────────────

function getVSReferences() {
  return [
    {
      citation:
        "Olson JJ. CNS Evidence-Based Clinical Practice Guidelines for the Treatment of Adults with Vestibular Schwannoma: Introduction and Methods Update. Neurosurgery. 2025.",
    },
    {
      citation:
        "Germano IM et al. CNS Systematic Review and Evidence-Based Guideline on the Role of Radiosurgery (SRS) and Radiation Therapy in the Management of Patients with Vestibular Schwannomas: Updates. Neurosurgery. 2025.",
    },
    {
      citation:
        "Van Gompel JJ et al. Surgical Resection For The Treatment Of Patients With Vestibular Schwannomas: Update. Neurosurgery. 2025.",
    },
    {
      citation:
        "Daher GS et al. CNS Systematic Review and Evidence-Based Guideline on Hearing Preservation Outcomes in Patients with Sporadic Vestibular Schwannoma: Update. Neurosurgery. 2025.",
    },
    {
      citation:
        "Graffeo CS et al. The Role Of Imaging In The Management Of Patients With Vestibular Schwannomas: Update. Neurosurgery. 2025.",
    },
    {
      citation:
        "Strickland BA et al. CNS Systematic Review and Evidence-Based Guidelines Update for the Role of Audiologic Screening in the Diagnosis and Management of Patients with Vestibular Schwannomas. Neurosurgery. 2025.",
    },
    {
      citation:
        "Patel NS et al. CNS Systematic Review and Evidence-Based Guidelines Update for the Role of Intraoperative Cranial Nerve Monitoring in the Management of Patients with Vestibular Schwannomas. Neurosurgery. 2025.",
    },
  ];
}

export function getRecommendationColor(rec: PrimaryRecommendation): string {
  switch (rec) {
    case "urgent_decompression":
      return "red";
    case "microsurgery_resection":
      return "blue";
    case "srs_gamma_knife":
      return "purple";
    case "fractionated_srt":
      return "indigo";
    case "subtotal_resection_plus_srs":
      return "orange";
    case "observation_active_surveillance":
      return "green";
    case "multidisciplinary_nf2":
      return "yellow";
    default:
      return "gray";
  }
}

export function getHearingClassLabel(cls: HearingClass): string {
  switch (cls) {
    case "class_a":
      return "AAO-HNS Class A (Excellent: PTA ≤30 dB, WRS ≥70%)";
    case "class_b":
      return "AAO-HNS Class B (Good: PTA ≤50 dB, WRS ≥50%)";
    case "class_c":
      return "AAO-HNS Class C (Serviceable: WRS ≥50%)";
    case "class_d":
      return "AAO-HNS Class D (Non-serviceable)";
    case "non_serviceable":
      return "Non-serviceable hearing (SDS <50% or PTA >50 dB)";
    default:
      return cls;
  }
}

export function getTumorSizeLabel(size: TumorSizeClass): string {
  switch (size) {
    case "intracanalicular":
      return "Intracanalicular (confined to IAC)";
    case "small":
      return "Small (<1.5 cm CPA component)";
    case "medium":
      return "Medium (1.5–3 cm CPA component)";
    case "large":
      return "Large (>3 cm CPA component)";
    default:
      return size;
  }
}
